{"apiVersion": "patchgate.io/v1alpha1", "kind": "Agent", "metadata": {"description": "Amazon CloudWatch Agent shipping memory/disk metrics and Patchgate logs.", "name": "cloudwatch-agent"}, "spec": {"install": {"linux": {"method": "package", "packages": {"dnf": ["amazon-cloudwatch-agent"]}, "postInstall": "install -d -m 0755 /opt/aws/amazon-cloudwatch-agent/etc /var/log/patchgate
cat > /opt/aws/amazon-cloudwatch-agent/etc/patchgate.json <<'JSON'
{
  "agent": { "metrics_collection_interval": 60 },
  "metrics": {
    "namespace": "Patchgate",
    "append_dimensions": { "InstanceId": "${aws:InstanceId}" },
    "metrics_collected": {
      "mem": { "measurement": ["mem_used_percent"] },
      "disk": { "measurement": ["used_percent"], "resources": ["/"] }
    }
  },
  "logs": {
    "logs_collected": {
      "files": {
        "collect_list": [
          { "file_path": "/var/log/patchgate/*.log", "log_group_name": "/patchgate/instances", "log_stream_name": "{instance_id}/patchgate" }
        ]
      }
    }
  }
}
JSON
/opt/aws/amazon-cloudwatch-agent/bin/amazon-cloudwatch-agent-ctl -a fetch-config -m ec2 -s \
  -c file:/opt/aws/amazon-cloudwatch-agent/etc/patchgate.json
"}, "windows": {"method": "msi", "postInstall": "$dir = "$env:ProgramData\Amazon\AmazonCloudWatchAgent"
New-Item -ItemType Directory -Force -Path $dir, "$env:ProgramData\Patchgate\logs" | Out-Null
$config = @'
{
  "metrics": {
    "namespace": "Patchgate",
    "append_dimensions": { "InstanceId": "${aws:InstanceId}" },
    "metrics_collected": {
      "Memory": { "measurement": ["% Committed Bytes In Use"] },
      "LogicalDisk": { "measurement": ["% Free Space"], "resources": ["C:"] }
    }
  },
  "logs": {
    "logs_collected": {
      "files": {
        "collect_list": [
          { "file_path": "C:\\ProgramData\\Patchgate\\logs\\*.log", "log_group_name": "/patchgate/instances", "log_stream_name": "{instance_id}/patchgate" }
        ]
      }
    }
  }
}
'@
# Write UTF-8 without BOM: Windows PowerShell 5.1 Set-Content adds one and the agent rejects it.
[IO.File]::WriteAllText("$dir\patchgate.json", $config, (New-Object Text.UTF8Encoding $false))
& "$env:ProgramFiles\Amazon\AmazonCloudWatchAgent\amazon-cloudwatch-agent-ctl.ps1" -a fetch-config -m ec2 -s -c "file:$dir\patchgate.json"
